test('roshambo: beats / playRound truth table', () => {
  assert.ok(beats('rock', 'scissors'));
  assert.ok(beats('scissors', 'paper'));
  assert.ok(beats('paper', 'rock'));
  for (const a of MOVES) for (const b of MOVES) {
