<!doctype html><meta charset="utf-8"><style>body{margin:0}iframe{border:0;width:100vw;height:100vh}</style>
<iframe id="f" src="/app/making-of.html"></iframe>
<script>
const p = new URLSearchParams(location.search);
f.onload = () => setTimeout(() => {
  const d = f.contentDocument;
  if (p.get('open')) {
    const withImg = [...d.querySelectorAll('details.tool')].filter((x) => x.querySelector('.tool-badge'));
    const t = withImg[+p.get('open')];
    t.open = true;
    t.closest('.turn').scrollIntoView();
  }
  if (p.get('turn')) d.getElementById('turn-' + p.get('turn')).scrollIntoView();
}, 1200);
</script>
EOF
